// Process each language file
langs.forEach(lang => {
  const filePath = path.join(transDir, `${lang}.ts`);
  let content = fs.readFileSync(filePath, 'utf8');

  // Extract JSON dictionary object
  const startIdx = content.indexOf('{');
  const endIdx = content.lastIndexOf('}');
  if (startIdx === -1 || endIdx === -1) {
    console.error(`Could not locate object in ${lang}.ts`);
    return;
  }

  let dict = {};
  try {
    dict = JSON.parse(content.substring(startIdx, endIdx + 1));
  } catch (e) {
    console.error(`JSON parse failed for ${lang}.ts:`, e.message);
    return;
  }

  // Inject keys
  let injectedCount = 0;
  for (const [key, langMap] of Object.entries(translations)) {
    const val = langMap[lang] || langMap['en'] || key;
    dict[key] = val;
    injectedCount++;
  }

  // Re-write file cleanly
  const updatedCode = `export const ${lang}: Record<string, string> = ${JSON.stringify(dict, null, 2)};\n`;
  fs.writeFileSync(filePath, updatedCode, 'utf8');
  console.log(`✓ Updated ${lang}.ts (+${injectedCount} entries, total: ${Object.keys(dict).length})`);
});
